"""Discover New Models: the models served now that this watch has never considered.

The ledger, a JSON file at `ledger`, holds every model the watch has
considered, with when and what became of it. A model is new when a provider
serves it and the ledger does not hold it, so one tried and rejected a week
ago never comes back. The first run records every model served as the
baseline and tries none, so a watch starts from what exists that night.

Only the models whose input and output take every one of `modalities`,
text unless named, and of `providers`, when named, are watched. At most
`limit` new models are tried a night, in identifier order; the rest wait,
unrecorded, for the next run.

The targets are checked first, so a mistake in them fails the watch before
anything is authorized: each names a workflow and a benchmark this instance
holds, and a latency and a cost above 0, and no workflow is named twice.
"""

import json
import os
import sys
from datetime import UTC, datetime
from pathlib import Path
from uuid import UUID

from azathoth import api

LEDGER_VERSION = 1
DEFAULT_LIMIT = 5
DEFAULT_MODALITIES = ("text",)
KEPT = (
    "identifier",
    "provider",
    "display_name",
    "input_modalities",
    "output_modalities",
    "context_window_tokens",
    "input_usd_per_million_tokens",
    "output_usd_per_million_tokens",
)


class WatchError(Exception):
    """The watch cannot go on; the message says why."""


def read_ledger(path):
    """Return the ledger at a path, or None before the first run."""

    if not path.exists():
        return None

    try:
        ledger = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, ValueError):
        raise WatchError(f"The ledger at {path} could not be read as JSON.") from None

    if (
        not isinstance(ledger, dict)
        or ledger.get("version") != LEDGER_VERSION
        or not isinstance(ledger.get("models"), dict)
    ):
        raise WatchError(f"The ledger at {path} is not a model-watch ledger.")

    return ledger


def write_ledger(path, ledger):
    """Write a ledger whole, replacing the one before only once it is written."""

    path.parent.mkdir(parents=True, exist_ok=True)
    written = path.with_name(f"{path.name}.tmp")
    written.write_text(f"{json.dumps(ledger, indent=2, sort_keys=True)}\n", encoding="utf-8")
    os.replace(written, path)


def number(value):
    """Return whether a value is a JSON number, and not a boolean."""

    return isinstance(value, int | float) and not isinstance(value, bool)


def check_targets(targets):
    """Return the targets, or refuse the first that is not one, by its place in the list."""

    if not isinstance(targets, list) or not targets:
        raise WatchError(
            "Name at least one target: a workflow, and the benchmark to try new models on."
        )

    named = set()

    for place, target in enumerate(targets, start=1):
        if not isinstance(target, dict):
            raise WatchError(f"Target {place} is not an object.")

        for key in ("workflow", "benchmark"):
            if not isinstance(target.get(key), str) or not target[key]:
                raise WatchError(f"Target {place} names no {key}.")

        for key in ("target_latency", "target_cost"):
            if not number(target.get(key)) or target[key] <= 0:
                raise WatchError(f"Target {place}'s {key} is not a number above 0.")

        if target["workflow"] in named:
            raise WatchError(
                f"Target {place} names workflow {target['workflow']} again; name each once."
            )

        named.add(target["workflow"])

    return targets


def check_limit(limit):
    """Return how many new models to try a night, or refuse one that is not a count."""

    if limit is None:
        return DEFAULT_LIMIT

    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
        raise WatchError("The limit is how many new models to try a night: 1 or more.")

    return limit


def watched(model, providers, modalities):
    """Return whether the watch watches a model, by its provider and modalities."""

    if providers and model["provider"] not in providers:
        return False

    return all(
        modality in model["input_modalities"] and modality in model["output_modalities"]
        for modality in modalities
    )


def plural(count, one, many):
    return f"{count} {one if count == 1 else many}"


def discover(served, ledger, *, providers, modalities, limit, now):
    """Return what the step says of the models served, and the ledger after it.

    `served` are the models providers serve now, as `azathoth.api` lists them.
    """

    stamp = now.astimezone(UTC).isoformat(timespec="seconds")

    if ledger is None:
        baseline = {model["identifier"]: {"seen": stamp, "status": "baseline"} for model in served}
        said = {
            "new_models": [],
            "new": 0,
            "waiting": 0,
            "first_run": True,
            "message": (
                f"Watching from now: {plural(len(served), 'model', 'models')} served tonight "
                "are the baseline, and only models released after them are tried."
            ),
        }

        return said, {"version": LEDGER_VERSION, "checked_at": stamp, "models": baseline}

    fresh = sorted(
        (
            model
            for model in served
            if model["identifier"] not in ledger["models"]
            and watched(model, providers, modalities)
        ),
        key=lambda model: model["identifier"],
    )
    chosen = fresh[:limit]
    waiting = len(fresh) - len(chosen)
    since = ledger.get("checked_at", "the last run")
    message = f"{plural(len(fresh), 'new model', 'new models')} since {since}."

    if waiting:
        message = f"{message} Trying {len(chosen)} tonight; {waiting} wait for the next run."

    said = {
        "new_models": [{key: model.get(key) for key in KEPT} for model in chosen],
        "new": len(fresh),
        "waiting": waiting,
        "first_run": False,
        "message": message,
    }

    return said, {**ledger, "checked_at": stamp}


def check_held(instance, targets):
    """Refuse a target whose workflow or benchmark this instance does not hold."""

    for place, target in enumerate(targets, start=1):
        for key, held in (("workflow", instance.workflows), ("benchmark", instance.benchmarks)):
            try:
                held.get(UUID(target[key]))
            except ValueError:
                raise WatchError(f"Target {place}'s {key} {target[key]} is not an ID.") from None
            except api.NotFoundError:
                raise WatchError(
                    f"Target {place}'s {key} {target[key]} is not on this instance."
                ) from None


def main():
    inputs = json.load(sys.stdin)

    try:
        targets = check_targets(inputs.get("targets"))
        limit = check_limit(inputs.get("limit"))
        providers = tuple(inputs.get("providers") or ())
        modalities = tuple(inputs.get("modalities") or DEFAULT_MODALITIES)
        path = Path(os.path.expanduser(inputs["ledger"]))
        ledger = read_ledger(path)
        database = os.environ.get("AZATHOTH_DATABASE", "azathoth.db")
        settings = api.ProviderSettings.from_environment()

        with api.open(database, providers=settings) as instance:
            check_held(instance, targets)
            served = [model.model_dump(mode="json") for model in instance.models.list()]
    except (WatchError, api.ApiError) as exc:
        sys.stderr.buffer.write(str(exc).encode("utf-8"))
        sys.exit(1)

    said, updated = discover(
        served,
        ledger,
        providers=providers,
        modalities=modalities,
        limit=limit,
        now=datetime.now(UTC),
    )
    write_ledger(path, updated)
    json.dump(said, sys.stdout)


if __name__ == "__main__":
    main()
